void require(bool b,const char *m){if(!b)throw std::runtime_error(m);}
struct Stop {std::atomic<bool> value{false};};
bool requested(void*p)noexcept{return static_cast<Stop*>(p)->value.load();}
Stop *owner=nullptr,*late=nullptr;
std::atomic<size_t> late_requests{0}, misses{0}, publications{0};
std::atomic<int> plan_target{-1}; size_t plan_length=0;
std::vector<double> expected_stores[4];
const std::complex<float>* fft_buffer=nullptr;
std::vector<std::complex<double>> fft_expected;
size_t fft_bins=0, fft_done=0;
const std::complex<float>* stft_fft_buffer=nullptr;
size_t stft_fft_frames=0,stft_fft_bins=0,stft_fft_cursor[64]{};
std::vector<std::complex<double>> stft_fft_expected;
bool close(double a,double b){return std::isfinite(a)&&std::abs(a-b)<=2e-6+2e-6*std::abs(b);}
// 2e-6 absolute accommodates the measured <7.5e-7 error with >2x
// rounding headroom; relative tolerance scales large DC/edge fixtures.
void prepare(const std::vector<float>&,const std::vector<float>&,int,int,const STFTConfig&);
std::atomic<int> target{-1};
std::atomic<size_t> joined{0};
std::atomic<size_t> counts[5], masks[5], entries{0}, active{0};
std::atomic<size_t> per_worker[5][64];
std::atomic<bool> bad{false}, clear_fft{false}, gate{false}, entered{false}, release_gate{false}, returned{false}, timedout{false};
std::mutex mutex;std::condition_variable cv;
size_t baseline_offset=0; double max_complex=0,max_mag=0;size_t fixtures=0;
void reset(Stop &s){owner=&s;late=nullptr;s.value=false;target=-1;joined=0;plan_target=-1;late_requests=0;bad=false;clear_fft=false;gate=false;entered=false;release_gate=false;returned=false;timedout=false;entries=0;active=0;for(int i=0;i<5;++i){counts[i]=0;masks[i]=0;for(auto &v:per_worker[i])v=0;}}
void observe(int stage,size_t worker,size_t begin,size_t count,float value)noexcept{
 active.fetch_add(1);entries.fetch_add(1);
 if(worker>=64||(stage!=4&&!std::isfinite(value))||count==0||(stage!=1&&stage!=4&&count>256))bad=true;
 counts[stage].fetch_add(count);if(worker<64){masks[stage].fetch_or(size_t(1)<<worker);per_worker[stage][worker].fetch_add(count);}
 if(stage!=1&&stage!=4&&!expected_stores[stage].empty()){
  // Framing's existing hook reports the last stored sample, other hooks begin.
  size_t ix=stage==0?begin+count-1:begin;
  if(ix>=expected_stores[stage].size()||!close(value,expected_stores[stage][ix]))bad=true;
 }
 if(late){late->value=true;++late_requests;}
 if(target.load()==stage){
  if(!gate.load())owner->value=true;
  if(gate.load()&&!entered.exchange(true)){
   cv.notify_all();std::unique_lock<std::mutex>l(mutex);
   if(!cv.wait_for(l,std::chrono::seconds(2),[]{return release_gate.load();})){timedout=true;release_gate=true;cv.notify_all();}
  }
 }
active.fetch_sub(1);cv.notify_all();
}
float wave(size_t j){return float(int(j*13%31)-15)/32;}
std::vector<float> waveform(int b,int s){std::vector<float>x(size_t(b)*s);for(size_t j=0;j<x.size();++j)x[j]=wave(j);return x;}
std::vector<std::complex<double>> oracle(const std::vector<float>&x,const std::vector<float>&w,int b,int samples,const STFTConfig &c){
 int pad=c.center?int(c.n_fft/2):0,frames=1+(samples+2*pad-int(c.n_fft))/int(c.hop_length),bins=int(c.n_fft/2+1),offset=int((c.n_fft-c.win_length)/2);
 std::vector<std::complex<double>>out(size_t(b)*bins*frames);
 for(int batch=0;batch<b;++batch)for(int t=0;t<frames;++t)for(int k=0;k<bins;++k){
  std::complex<double>sum{};
  for(int j=0;j<c.n_fft;++j){float v=0;if(j>=offset&&j<offset+c.win_length){int ix=t*int(c.hop_length)-pad+j;bool valid=ix>=0&&ix<samples;
   if(!valid&&c.pad_mode==STFTPadMode::Reflect){int period=2*(samples-1);ix=((ix%period)+period)%period;if(ix>=samples)ix=period-ix;valid=true;}
   if(valid)v=x[size_t(batch)*samples+ix]*w[j-offset];}
   double a=-2*std::acos(-1.)*k*j/c.n_fft;sum+=double(v)*std::complex<double>(std::cos(a),std::sin(a));
  }out[(size_t(batch)*bins+k)*frames+t]=sum;
 }return out;
}
void prepare(const std::vector<float>&x,const std::vector<float>&w,int batch,int samples,const STFTConfig&c){
 int pad=c.center?int(c.n_fft/2):0, frames=1+(samples+2*pad-int(c.n_fft))/int(c.hop_length),offset=int((c.n_fft-c.win_length)/2);
 for(auto &v:expected_stores)v.clear();
 expected_stores[0].resize(size_t(batch)*frames*c.n_fft);
 for(int b=0;b<batch;++b)for(int t=0;t<frames;++t)for(int j=0;j<c.win_length;++j){
 int ix=t*int(c.hop_length)-pad+offset+j;float v=0;
 if(c.pad_mode==STFTPadMode::Reflect){int period=2*(samples-1);ix=((ix%period)+period)%period;if(ix>=samples)ix=period-ix;}
 if(ix>=0&&ix<samples)v=x[size_t(b)*samples+ix]*w[j];
 expected_stores[0][(size_t(b)*frames+t)*c.n_fft+offset+j]=v;
 }
 auto ref=oracle(x,w,batch,samples,c);
 stft_fft_expected.resize(ref.size());
 size_t bins=size_t(c.n_fft/2+1);
 for(int b=0;b<batch;++b)for(int t=0;t<frames;++t)for(size_t k=0;k<bins;++k)
  stft_fft_expected[(size_t(b)*frames+t)*bins+k]=ref[(size_t(b)*bins+k)*frames+t];
 for(auto z:ref){expected_stores[2].push_back(z.real());expected_stores[2].push_back(z.imag());expected_stores[3].push_back(std::abs(z));}
}
void check_output(const STFTResult&r,const std::vector<std::complex<double>>&ref,int batch,int frames,int bins,bool mag){
 require(r.status==FFTStatus::Completed&&r.output,"fresh run Completed");
 std::vector<int64_t> shape={batch,bins,frames};if(!mag)shape.push_back(2);
 require(r.output->shape==shape&&r.output->values.size()==ref.size()*(mag?1:2),"independent output shape");
 for(size_t i=0;i<ref.size();++i){if(mag)require(close(r.output->values[i],std::abs(ref[i])),"fresh magnitude DFT");else require(close(r.output->values[2*i],ref[i].real())&&close(r.output->values[2*i+1],ref[i].imag()),"fresh real and imaginary DFT");}
}
void parity(const std::vector<float>&x,const std::vector<float>&w,int batch,int samples,const STFTConfig&c,bool frozen=false){
 Stop stop;reset(stop);prepare(x,w,batch,samples,c);auto copy=x,win=w;STFT stft;
 auto legacy=stft.compute_complex(x,w,batch,samples,c,1),lm=stft.compute_magnitude(x,w,batch,samples,c,1);
 for(bool callback:{false,true}){
 auto a=stft.compute_complex(x,w,batch,samples,c,1,callback?FFTStop{requested,&stop}:FFTStop{});
 auto m=stft.compute_magnitude(x,w,batch,samples,c,1,callback?FFTStop{requested,&stop}:FFTStop{});
 require(a.status==FFTStatus::Completed&&a.output&&m.status==FFTStatus::Completed&&m.output,"completed output");
 require(a.output->shape==legacy.shape&&a.output->values.size()==legacy.values.size()&&std::memcmp(a.output->values.data(),legacy.values.data(),legacy.values.size()*4)==0,"complex legacy bitwise");
 require(m.output->shape==lm.shape&&m.output->values.size()==lm.values.size()&&std::memcmp(m.output->values.data(),lm.values.data(),lm.values.size()*4)==0,"magnitude legacy bitwise");
 }
 auto ref=oracle(x,w,batch,samples,c);require(legacy.values.size()==ref.size()*2&&lm.values.size()==ref.size(),"oracle layout size");
 for(size_t j=0;j<ref.size();++j){double er=std::abs(legacy.values[2*j]-ref[j].real()),ei=std::abs(legacy.values[2*j+1]-ref[j].imag()),em=std::abs(lm.values[j]-std::abs(ref[j]));max_complex=std::max(max_complex,std::max(er,ei));max_mag=std::max(max_mag,em);
 require(er<=2e-6+2e-6*std::abs(ref[j].real())&&ei<=2e-6+2e-6*std::abs(ref[j].imag()),"double DFT complex");require(em<=2e-6+2e-6*std::abs(ref[j]),"double DFT magnitude");}
 require(copy==x&&win==w,"input immutability");++fixtures;
 (void)frozen;
}
